/// Returns the minimal NumPy dtype that can hold the given `i8`
///
///   - non‐negative inputs fit in an unsigned byte (UInt8)
///   - strictly negative inputs require a signed byte (Int8)
#[requires(true)]
#[ensures(
    // exactly the two cases
    (value >= 0 && result == NumpyDType::UInt8)
    ||
    (value < 0  && result == NumpyDType::Int8)
)]
pub fn min_scalar_type(value: i8) -> NumpyDType {
    // Since all types are at least 8 bits and Int8 covers [-128, 127],
    // the only question is unsigned vs. signed for non-negative values.
    if value >= 0 {
        NumpyDType::UInt8
    } else {
        NumpyDType::Int8
    }
}

